from collections import deque

from AlgorithmImports import *


class ExactStrategyAlgorithm(QCAlgorithm):
    SMA_PERIOD = 200
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = [
            self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in tickers
        ]

        self.SetWarmUp(250, Resolution.Daily)

        self.close_windows = {
            symbol: deque(maxlen=self.SMA_PERIOD + 1)
            for symbol in self.symbols
        }

        self.red_streak = {symbol: 0 for symbol in self.symbols}

        self.rsi = self.RSI(
            self.symbols[1],
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol):
                close = float(data.Bars[symbol].Close)
                window = self.close_windows[symbol]

                previous_close = window[0] if len(window) > 0 else None
                window.appendleft(close)

                if previous_close is not None and close < previous_close:
                    self.red_streak[symbol] += 1
                else:
                    self.red_streak[symbol] = 0

        if self.IsWarmingUp:
            return

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        spy = self.symbols[0]
        aapl = self.symbols[1]

        spy_window = self.close_windows[spy]
        aapl_window = self.close_windows[aapl]

        if len(spy_window) < self.SMA_PERIOD + 1:
            return

        if not self.rsi.IsReady:
            return

        spy_close = spy_window[0]
        spy_previous_close = spy_window[1]

        spy_sma_today = sum(
            spy_window[i] for i in range(self.SMA_PERIOD)
        ) / self.SMA_PERIOD

        spy_sma_yesterday = sum(
            spy_window[i] for i in range(1, self.SMA_PERIOD + 1)
        ) / self.SMA_PERIOD

        aapl_rsi = float(self.rsi.Current.Value)

        spy_crossed_below = (
            spy_previous_close <= spy_sma_yesterday
            and spy_close < spy_sma_today
        )

        spy_crossed_above = (
            spy_previous_close <= spy_sma_yesterday
            and spy_close > spy_sma_today
        )

        if self.strategy_a_lot > 0 and spy_crossed_below:
            self.MarketOrder(spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and aapl_rsi > 60:
            self.MarketOrder(aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crossed_above:
            target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
            shares = int(target_value / spy_close)

            if shares > 0:
                self.MarketOrder(spy, shares)
                self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and self.red_streak[aapl] >= 3:
            if float(self.Portfolio.Cash) >= 20000:
                shares = int(20000 / float(data.Bars[aapl].Close))

                if shares > 0:
                    self.MarketOrder(aapl, shares)
                    self.strategy_b_lot = shares

