from AlgorithmImports import *
import math


class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.spy, 200, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.SetWarmUp(200, Resolution.Daily)

        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        if self.spy in data.Bars:
            spy_bar = data.Bars[self.spy]
            if self.aapl in data.Bars:
                aapl_bar = data.Bars[self.aapl]
            else:
                aapl_bar = None
        else:
            spy_bar = None
            aapl_bar = data.Bars[self.aapl] if self.aapl in data.Bars else None

        if aapl_bar is not None and self.aapl_previous_close is not None:
            if aapl_bar.Close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if self.IsWarmingUp:
            if spy_bar is not None and self.spy_sma.IsReady:
                self.spy_previous_close = spy_bar.Close
                self.spy_previous_sma = self.spy_sma.Current.Value

            if aapl_bar is not None:
                self.aapl_previous_close = aapl_bar.Close

            return

        if spy_bar is None or aapl_bar is None:
            if spy_bar is not None and self.spy_sma.IsReady:
                self.spy_previous_close = spy_bar.Close
                self.spy_previous_sma = self.spy_sma.Current.Value

            if aapl_bar is not None:
                self.aapl_previous_close = aapl_bar.Close

            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            self.spy_previous_close = spy_bar.Close
            self.spy_previous_sma = self.spy_sma.Current.Value
            self.aapl_previous_close = aapl_bar.Close
            return

        current_spy_sma = self.spy_sma.Current.Value
        current_aapl_rsi = self.aapl_rsi.Current.Value

        spy_crosses_above = (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_previous_close <= self.spy_previous_sma
            and spy_bar.Close > current_spy_sma
        )

        spy_crosses_below = (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_previous_close >= self.spy_previous_sma
            and spy_bar.Close < current_spy_sma
        )

        if self.strategy_a_shares > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and current_aapl_rsi > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crosses_above:
            quantity = int(
                math.floor(
                    0.40 * self.Portfolio.TotalPortfolioValue / spy_bar.Close
                )
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                quantity = int(math.floor(20000 / aapl_bar.Close))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_shares = quantity

        self.spy_previous_close = spy_bar.Close
        self.spy_previous_sma = current_spy_sma
        self.aapl_previous_close = aapl_bar.Close

from AlgorithmImports import *


class TwoSlotStrategy(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(
            self.spy, self.SMA_PERIOD, Resolution.Daily
        )
        self.aapl_rsi = self.RSI(
            self.aapl, self.RSI_PERIOD, MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(
            max(self.SMA_PERIOD, self.RSI_PERIOD) + 1,
            Resolution.Daily
        )

        self.spy_lot = 0
        self.aapl_lot = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_observations = 0

    def OnData(self, data: Slice):
        bars = data.Bars

        if self.spy in bars:
            spy_close = float(bars[self.spy].Close)

            if self.previous_spy_close is not None:
                spy_sma_value = (
                    float(self.spy_sma.Current.Value)
                    if self.spy_sma.IsReady else None
                )
            else:
                spy_sma_value = None
        else:
            spy_close = None
            spy_sma_value = None

        if self.aapl in bars:
            aapl_close = float(bars[self.aapl].Close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            else:
                self.aapl_red_streak = 0

            self.aapl_observations += 1
        else:
            aapl_close = None

        all_bars_present = all(symbol in bars for symbol in self.symbols.values())

        if (
            not self.IsWarmingUp
            and all_bars_present
            and self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.aapl_observations >= 3
        ):
            spy_crosses_below = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_close > 0
                and spy_close < spy_sma_value
            )

            spy_crosses_above = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_close > spy_sma_value
            )

            if self.spy_lot > 0 and spy_crosses_below:
                self.MarketOrder(self.spy, -self.spy_lot)
                self.spy_lot = 0

            aapl_rsi_value = float(self.aapl_rsi.Current.Value)

            if self.aapl_lot > 0 and aapl_rsi_value > 60:
                self.MarketOrder(self.aapl, -self.aapl_lot)
                self.aapl_lot = 0

            if self.spy_lot == 0 and spy_crosses_above:
                quantity = int(
                    (0.40 * self.Portfolio.TotalPortfolioValue)
                    / spy_close
                )
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.spy_lot = quantity

            if (
                self.aapl_lot == 0
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20000
            ):
                quantity = int(20000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.aapl_lot = quantity

        if spy_close is not None:
            self.previous_spy_close = spy_close
            if spy_sma_value is not None:
                self.previous_spy_sma = spy_sma_value

        if aapl_close is not None:
            self.previous_aapl_close = aapl_close

