from AlgorithmImports import *
import math


class ExactStrategySystem(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.spy, self.SMA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(self.SMA_PERIOD + self.RSI_PERIOD + 2, Resolution.Daily)

        self.spy_lot = 0
        self.aapl_lot = 0

        self.spy_prev_close = None
        self.spy_prev_sma = None
        self.spy_prev_sma_ready = False

        self.aapl_prev_close = None
        self.aapl_red_streak = 0

        self.pending_orders = {}

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        aapl_bar = data.Bars[self.aapl] if self.aapl in data.Bars else None
        ibm_bar = data.Bars[self.ibm] if self.ibm in data.Bars else None
        bac_bar = data.Bars[self.bac] if self.bac in data.Bars else None
        aig_bar = data.Bars[self.aig] if self.aig in data.Bars else None

        if aapl_bar is not None:
            if self.aapl_prev_close is not None:
                if aapl_bar.Close < self.aapl_prev_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_prev_close = aapl_bar.Close

        current_spy_sma = float(self.spy_sma.Current.Value)
        current_spy_sma_ready = self.spy_sma.IsReady

        spy_cross_above = False
        spy_cross_below = False

        if spy_bar is not None and self.spy_prev_close is not None:
            if self.spy_prev_sma_ready and current_spy_sma_ready:
                spy_cross_above = (
                    self.spy_prev_close <= self.spy_prev_sma
                    and spy_bar.Close > current_spy_sma
                )
                spy_cross_below = (
                    self.spy_prev_close >= self.spy_prev_sma
                    and spy_bar.Close < current_spy_sma
                )

        if spy_bar is not None:
            self.spy_prev_close = spy_bar.Close
            self.spy_prev_sma = current_spy_sma
            self.spy_prev_sma_ready = current_spy_sma_ready

        if self.IsWarmingUp:
            return

        if (
            spy_bar is None
            or aapl_bar is None
            or ibm_bar is None
            or bac_bar is None
            or aig_bar is None
        ):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        if self.spy_lot > 0 and spy_cross_below and self.spy not in self.pending_orders:
            self._submit_order("spy", self.spy, -self.spy_lot)

        if self.aapl_lot > 0 and self.aapl_rsi.Current.Value > 60:
            if self.aapl not in self.pending_orders:
                self._submit_order("aapl", self.aapl, -self.aapl_lot)

        if self.spy_lot == 0 and self.spy not in self.pending_orders:
            if spy_cross_above:
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                quantity = int(math.floor(target_value / spy_bar.Close))
                if quantity > 0:
                    self._submit_order("spy", self.spy, quantity)

        if self.aapl_lot == 0 and self.aapl not in self.pending_orders:
            if self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    quantity = int(math.floor(20000 / aapl_bar.Close))
                    if quantity > 0:
                        self._submit_order("aapl", self.aapl, quantity)

    def _submit_order(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity)
        if ticket is not None and ticket.OrderId > 0:
            self.pending_orders[ticket.OrderId] = strategy

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId
        if order_id not in self.pending_orders:
            return

        strategy = self.pending_orders[order_id]
        fill_quantity = order_event.FillQuantity

        if strategy == "spy":
            self.spy_lot += fill_quantity
            if self.spy_lot < 0:
                self.spy_lot = 0
        elif strategy == "aapl":
            self.aapl_lot += fill_quantity
            if self.aapl_lot < 0:
                self.aapl_lot = 0

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled,
        ):
            if order_event.Status != OrderStatus.PartiallyFilled:
                del self.pending_orders[order_id]
