        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.aapl_rsi = self.RSI(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD)
        self.spy_previous_close = None
        self.spy_previous_ma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.pending_orders = {}

        self.SetWarmUp(self.MOVING_AVERAGE_PERIOD + 1, Resolution.Daily)

    def OnData(self, data):
        if self.spy in data.Bars:
            spy_close = data.Bars[self.spy].Close
            self.spy_closes.append(spy_close)

            spy_ma = None
            if len(self.spy_closes) == self.MOVING_AVERAGE_PERIOD:
                spy_ma = sum(self.spy_closes) / self.MOVING_AVERAGE_PERIOD

            self.spy_current_close = spy_close
            self.spy_current_ma = spy_ma

        if self.aapl in data.Bars:
            aapl_close = data.Bars[self.aapl].Close

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close

        if self.spy not in data.Bars:
            return
        if self.aapl not in data.Bars:
            return
        if self.ibm not in data.Bars:
            return
        if self.bac not in data.Bars:
            return
        if self.aig not in data.Bars:
            return

        if self.spy_previous_close is None:
            self.spy_previous_close = self.spy_current_close
            self.spy_previous_ma = self.spy_current_ma
            return

        spy_crossed_above = (
            self.spy_previous_ma is not None
            and self.spy_current_ma is not None
            and self.spy_previous_close <= self.spy_previous_ma
            and self.spy_current_close > self.spy_current_ma
        )

        spy_crossed_below = (
            self.spy_previous_ma is not None
            and self.spy_current_ma is not None
            and self.spy_previous_close >= self.spy_previous_ma
            and self.spy_current_close < self.spy_current_ma
        )

        aapl_sell_reason = (
            self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        )

        if not self.IsWarmingUp:
            if (
                self.strategy_a_lot > 0
                and "A_SELL" not in self.pending_orders
                and spy_crossed_below
            ):
                self._submit_order(
                    "A_SELL",
                    self.spy,
                    -self.strategy_a_lot,
                    "Strategy A sell"
                )

            if (
                self.strategy_b_lot > 0
                and "B_SELL" not in self.pending_orders
                and aapl_sell_reason
            ):
                self._submit_order(
                    "B_SELL",
                    self.aapl,
                    -self.strategy_b_lot,
                    "Strategy B sell"
                )

            if (
                self.strategy_a_lot == 0
                and "A_BUY" not in self.pending_orders
                and spy_crossed_above
            ):
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                quantity = int(math.floor(target_value / self.spy_current_close))

                if quantity > 0:
                    self._submit_order(
                        "A_BUY",
                        self.spy,
                        quantity,
                        "Strategy A buy"
                    )

            if (
                self.strategy_b_lot == 0
                and "B_BUY" not in self.pending_orders
                and self.Portfolio.Cash >= self.AAPL_BUY_AMOUNT
            ):
                quantity = int(
                    math.floor(self.AAPL_BUY_AMOUNT / data.Bars[self.aapl].Close)
                )

                if quantity > 0:
                    self._submit_order(
                        "B_BUY",
                        self.aapl,
                        quantity,
                        "Strategy B buy"
                    )

        self.spy_previous_close = self.spy_current_close
        self.spy_previous_ma = self.spy_current_ma

    def _submit_order(self, key, symbol, quantity, tag):
        self.pending_orders[key] = True
        self.MarketOrder(symbol, quantity, tag=tag)

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order_event.FillQuantity != 0:
            filled = abs(order_event.FillQuantity)

            if order.Direction == OrderDirection.Buy:
                if order.Tag == "Strategy A buy":
                    self.strategy_a_lot += filled
                elif order.Tag == "Strategy B buy":
                    self.strategy_b_lot += filled
            elif order.Direction == OrderDirection.Sell:
                if order.Tag == "Strategy A sell":
                    self.strategy_a_lot = max(0, self.strategy_a_lot - filled)
                elif order.Tag == "Strategy B sell":
                    self.strategy_b_lot = max(0, self.strategy_b_lot - filled)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if order.Tag == "Strategy A buy":
                self.pending_orders.pop("A_BUY", None)
            elif order.Tag == "Strategy A sell":
                self.pending_orders.pop("A_SELL", None)
            elif order.Tag == "Strategy B buy":
                self.pending_orders.pop("B_BUY", None)
            elif order.Tag == "Strategy B sell":
                self.pending_orders.pop("B_SELL", None)

