                    self._submit_order(
                        "A_BUY",
                        self.spy,
                        quantity,
                        "Strategy A buy"
                    )

            if (
                self.strategy_b_lot == 0
                and "B_BUY" not in self.pending_orders
                and self.Portfolio.Cash >= self.AAPL_BUY_AMOUNT
            ):
                quantity = int(
                    math.floor(self.AAPL_BUY_AMOUNT / data.Bars[self.aapl].Close)
                )

                if quantity > 0:
                    self._submit_order(
                        "B_BUY",
                        self.aapl,
                        quantity,
                        "Strategy B buy"
                    )

        self.spy_previous_close = self.spy_current_close
        self.spy_previous_ma = self.spy_current_ma

    def _submit_order(self, key, symbol, quantity, tag):
        self.pending_orders[key] = True
        self.MarketOrder(symbol, quantity, tag=tag)

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order_event.FillQuantity != 0:
            filled = abs(order_event.FillQuantity)

            if order.Direction == OrderDirection.Buy:
                if order.Tag == "Strategy A buy":
                    self.strategy_a_lot += filled
                elif order.Tag == "Strategy B buy":
                    self.strategy_b_lot += filled
            elif order.Direction == OrderDirection.Sell:
                if order.Tag == "Strategy A sell":
                    self.strategy_a_lot = max(0, self.strategy_a_lot - filled)
                elif order.Tag == "Strategy B sell":
                    self.strategy_b_lot = max(0, self.strategy_b_lot - filled)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if order.Tag == "Strategy A buy":
                self.pending_orders.pop("A_BUY", None)
            elif order.Tag == "Strategy A sell":
                self.pending_orders.pop("A_SELL", None)
            elif order.Tag == "Strategy B buy":
                self.pending_orders.pop("B_BUY", None)
            elif order.Tag == "Strategy B sell":
                self.pending_orders.pop("B_SELL", None)
