class ExactStrategySystem(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 200
    RSI_PERIOD = 14
    AAPL_BUY_AMOUNT = 20000

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_ma = SimpleMovingAverage(self.MOVING_AVERAGE_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD,
            MovingAverageType.Wilders
        )

        self.previous_closes = {}
        self.previous_spy_ma = None
        self.previous_aapl_rsi = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.SetWarmUp(self.MOVING_AVERAGE_PERIOD, Resolution.Daily)

    def OnData(self, data: Slice):
        present_bars = {
            symbol: data.Bars[symbol]
            for symbol in self.symbols
            if symbol in data.Bars
        }

        for symbol, bar in present_bars.items():
            previous_close = self.previous_closes.get(symbol)

            if symbol == self.aapl:
                if previous_close is None:
                    self.aapl_red_streak = 0
                elif bar.Close < previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_closes[symbol] = bar.Close

        if self.spy in present_bars:
            self.spy_ma.Update(self.Time, present_bars[self.spy].Close)

        if self.aapl in present_bars:
            self.aapl_rsi.Update(self.Time, present_bars[self.aapl].Close)

        if len(present_bars) != len(self.symbols):
            return

        if self.IsWarmingUp:
            if self.spy_ma.IsReady:
                self.previous_spy_ma = self.spy_ma.Current.Value
            if self.aapl_rsi.IsReady:
                self.previous_aapl_rsi = self.aapl_rsi.Current.Value
            return

        if not self.spy_ma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = present_bars[self.spy].Close
        current_spy_ma = self.spy_ma.Current.Value
        current_aapl_rsi = self.aapl_rsi.Current.Value

        spy_crossed_below = (
            self.previous_spy_ma is not None
            and self.previous_closes[self.spy] <= self.previous_spy_ma
            and spy_close < current_spy_ma
        )

        spy_crossed_above = (
            self.previous_spy_ma is not None
            and self.previous_closes[self.spy] <= self.previous_spy_ma
            and spy_close > current_spy_ma
        )

        aapl_rsi_above_60 = current_aapl_rsi > 60

        if self.strategy_a_lot > 0 and spy_crossed_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and aapl_rsi_above_60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crossed_above:
            quantity = int(
                (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if (
            self.strategy_b_lot == 0
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= self.AAPL_BUY_AMOUNT
        ):
            quantity = int(self.AAPL_BUY_AMOUNT / present_bars[self.aapl].Close)
            if quantity > 0:
                self.MarketOrder(self.aapl, quantity)
                self.strategy_b_lot = quantity

        self.previous_spy_ma = current_spy_ma
        self.previous_aapl_rsi = current_aapl_rsi

