                spy_cross_above = False
                spy_cross_below = False
        else:
            spy_cross_above = False
            spy_cross_below = False

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.Close

        if spy_bar is not None and self.spy_sma.IsReady:
            current_spy_sma = self.spy_sma.Current.Value
        else:
            current_spy_sma = None

        full_day = all(
            self._get_bar(data, symbol) is not None
            for symbol in (self.spy, self.aapl, self.ibm, self.bac, self.aig)
        )

        if full_day:
            if self.strategy_a_lot > 0 and spy_cross_below:
                self._sell_strategy_a()

            if self.strategy_b_lot > 0 and self.aapl_rsi.IsReady:
                if self.aapl_rsi.Current.Value > 60:
                    self._sell_strategy_b()

            if self.strategy_a_lot == 0 and spy_cross_above:
                quantity = int(
                    (0.40 * self.Portfolio.TotalPortfolioValue)
                    / spy_bar.Close
                )
                if quantity > 0:
                    self._buy_strategy_a(quantity)

            if (
                self.strategy_b_lot == 0
                and self.aapl_rsi.IsReady
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20000
            ):
                quantity = int(20000 / aapl_bar.Close)
                if quantity > 0:
                    self._buy_strategy_b(quantity)

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            if current_spy_sma is not None:
                self.previous_spy_sma = current_spy_sma

    def _get_bar(self, data, symbol):
        if data.Bars.ContainsKey(symbol):
            return data.Bars[symbol]
        return None

    def _buy_strategy_a(self, quantity):
        ticket = self.MarketOrder(self.spy, quantity)
        self.order_strategy[ticket.OrderId] = ("A", quantity)

    def _sell_strategy_a(self):
        if self.strategy_a_lot > 0:
            ticket = self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.order_strategy[ticket.OrderId] = ("A", -self.strategy_a_lot)

    def _buy_strategy_b(self, quantity):
        ticket = self.MarketOrder(self.aapl, quantity)
        self.order_strategy[ticket.OrderId] = ("B", quantity)

    def _sell_strategy_b(self):
        if self.strategy_b_lot > 0:
            ticket = self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.order_strategy[ticket.OrderId] = ("B", -self.strategy_b_lot)

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        strategy = self.order_strategy.get(order_event.OrderId)
        if strategy is None:
            return

        name, _ = strategy
        fill_quantity = int(order_event.FillQuantity)

        if name == "A":
            self.strategy_a_lot += fill_quantity
        elif name == "B":
            self.strategy_b_lot += fill_quantity

        del self.order_strategy[order_event.OrderId]
