        symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]
        available = {symbol: symbol in data.Bars for symbol in symbols}

        # Continuously update market-state quantities from whatever data exists.
        for symbol in symbols:
            if available[symbol]:
                self.previous_closes.setdefault(symbol, None)

        if available[self.aapl]:
            aapl_close = data.Bars[self.aapl].Close
            previous_aapl_close = self.previous_closes.get(self.aapl)

            if previous_aapl_close is not None:
                if aapl_close < previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        # Rule evaluation is skipped if any subscribed ticker is missing.
        if not all(available.values()):
            self._update_previous_values(data, available)
            return

        if self.IsWarmingUp:
            self._update_previous_values(data, available)
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # Strategy A: evaluate sell before buy.
        if self.strategy_a_shares > 0:
            if (
                self.previous_spy_sma is not None
                and self.spy_sma.IsReady
                and spy_close < self.spy_sma.Current.Value
                and self.previous_closes.get(self.spy) is not None
                and self.previous_closes[self.spy] >= self.previous_spy_sma
            ):
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_a_shares == 0:
            if (
                self.previous_spy_sma is not None
                and self.spy_sma.IsReady
                and spy_close > self.spy_sma.Current.Value
                and self.previous_closes.get(self.spy) is not None
                and self.previous_closes[self.spy] <= self.previous_spy_sma
            ):
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                shares = int(target_value / spy_close)

                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.strategy_a_shares = shares

        # Strategy B: evaluate sell before buy.
        if self.strategy_b_shares > 0:
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_b_shares == 0:
            if self.aapl_rsi.IsReady and self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    shares = int(20000 / aapl_close)

                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.strategy_b_shares = shares

        self._update_previous_values(data, available)

    def _update_previous_values(self, data, available):
        for symbol, exists in available.items():
            if exists:
                self.previous_closes[symbol] = data.Bars[symbol].Close

        if self.spy_sma.IsReady:
            self.previous_spy_sma = self.spy_sma.Current.Value

